#!/usr/bin/env bash
# Compiles a program generated by `sigflowc --emit=cuda` against the rfgpu kernels.
#
#   compiler/tools/build_cuda.sh PROGRAM.cu OUTPUT
#
# RFGPU_BUILD is the rfgpu build directory holding librfgpu_ops.a (default: build/ at the
# repository root, as in the Quick start); NVCC is the compiler (default: nvcc on PATH, else
# /usr/local/cuda/bin/nvcc). Builds for the GPU in this machine, with -O3 as Release does.
set -euo pipefail
if [ $# -ne 2 ]; then
  echo "usage: $0 PROGRAM.cu OUTPUT" >&2
  exit 2
fi
root="$(cd "$(dirname "$0")/../.." && pwd)"
build="${RFGPU_BUILD:-$root/build}"
nvcc="${NVCC:-$(command -v nvcc || echo /usr/local/cuda/bin/nvcc)}"
if [ ! -f "$build/librfgpu_ops.a" ]; then
  echo "error: $build/librfgpu_ops.a not found; build rfgpu first or set RFGPU_BUILD" >&2
  exit 1
fi
exec "$nvcc" -std=c++17 -O3 -arch=native -I"$root/src" "$1" "$build/librfgpu_ops.a" -lcufft \
  -o "$2"
